	virtual void instanceConstants(int sample_rate) {
		fSampleRate = sample_rate;
		fConst0 = std::min<float>(1.92e+05f, std::max<float>(1.0f, static_cast<float>(fSampleRate)));
		fConst1 = 1.0f / std::max<float>(1.0f, 0.02f * fConst0);
		fConst2 = 1.0f / std::tan(1063.7433f / fConst0);
		fConst3 = 1.0f / (fConst2 + 1.0f);
		fConst4 = 1.0f - fConst2;
		fConst5 = 4.0f / fConst0;
		fConst6 = std::exp(-(1e+02f / fConst0));
		fConst7 = std::max<float>(1.0f, 0.001f * fConst0);
		fConst8 = 1.0f / fConst7;
		fConst9 = 1.0f / fConst0;
		fConst10 = 0.0045454544f / fConst0;
		fConst11 = 3.1415927f / fConst0;
		fConst12 = std::tan(628.31854f / fConst0);
		fConst13 = SimianVoice_faustpower2_f(fConst12);
		fConst14 = 1.0f / fConst12;
		fConst15 = (fConst14 + 1.4142135f) / fConst12 + 1.0f;
		fConst16 = 1.0f / (fConst13 * fConst15);
		iConst17 = static_cast<int>(fConst0 / std::min<float>(fConst0, 4.8e+04f));
		fConst18 = 1.0f / fConst15;
		fConst19 = (fConst14 + -1.4142135f) / fConst12 + 1.0f;
		fConst20 = 2.0f * (1.0f - 1.0f / fConst13);
		fConst21 = 1.0f / std::max<float>(1.0f, 0.019f * fConst0);
	}
	
